<?php
// Clothing Shop Management System — standalone interface prototype.
// Product and order examples are local sample data; connect these views to MySQL to persist records.
$isHttps = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
session_set_cookie_params(['httponly'=>true, 'secure'=>$isHttps, 'samesite'=>'Lax']);
$sessionPathCandidates = [
    __DIR__ . DIRECTORY_SEPARATOR . 'sessions',
    rtrim(sys_get_temp_dir(), "\\/") . DIRECTORY_SEPARATOR . 'thread-form-sessions',
];
$sessionStorage = null;
foreach ($sessionPathCandidates as $candidate) {
    if (!is_dir($candidate) && !@mkdir($candidate, 0700, true) && !is_dir($candidate)) continue;
    if (is_writable($candidate)) { $sessionStorage = $candidate; break; }
}
if ($sessionStorage === null || session_save_path($sessionStorage) === false) {
    http_response_code(500);
    exit('Session storage is not writable. Configure a writable PHP session directory.');
}
session_start();
if (empty($_SESSION['login_csrf'])) $_SESSION['login_csrf'] = bin2hex(random_bytes(32));
$userSignedIn = isset($_SESSION['user_id'], $_SESSION['user_email'], $_SESSION['user_role']);
$userEmail = $userSignedIn ? (string)$_SESSION['user_email'] : '';
$userInitial = $userSignedIn ? strtoupper(substr($userEmail, 0, 1)) : 'J';
