<div class="modal-backdrop" id="loginModal"><form class="modal" id="loginForm" method="post" action="login.php"><input type="hidden" name="action" value="login"><input type="hidden" name="csrf_token" value="<?=e((string)$_SESSION['login_csrf'])?>"><button type="button" class="close" data-close-modal aria-label="Close">×</button><span class="eyebrow">Welcome back</span><h2>Sign in</h2><p>Sign in to view your profile and keep shopping.</p><label for="loginEmail">Email address</label><input id="loginEmail" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="loginPassword">Password</label><input id="loginPassword" name="password" type="password" autocomplete="current-password" minlength="6" required placeholder="At least 6 characters"><button class="btn" type="submit">Sign in</button><p style="text-align:center;margin:14px 0 0;font-size:11px">New here? <button type="button" id="registerLink" style="border:0;background:none;color:var(--olive-dark);text-decoration:underline;padding:0">Create an account</button></p></form></div><div class="toast" id="toast"></div>
<script>
const products=<?=json_encode(array_map(fn($p)=>['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'stock'=>$p['stock'],'image'=>$p['image']],$products),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;
let cart={};let activeCategory='All';
function peso(n){return '₱'+Number(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function renderCart(){let count=0,total=0;const box=document.getElementById('cartItems');box.innerHTML='';Object.values(cart).forEach(item=>{count+=item.qty;total+=item.qty*item.price;const row=document.createElement('div');row.className='cart-line';row.innerHTML=`<img src="${item.image}" alt=""><div><strong>${item.name}</strong><p>${peso(item.price)} each</p><div class="qty"><button data-qty="${item.id}" data-step="-1" aria-label="Decrease quantity">−</button><span>${item.qty}</span><button data-qty="${item.id}" data-step="1" aria-label="Increase quantity">+</button></div><button class="remove" data-remove="${item.id}">Remove</button></div><strong>${peso(item.qty*item.price)}</strong>`;box.appendChild(row)});if(!count)box.innerHTML='<div class="empty">Your bag is waiting for something lovely.</div>';document.getElementById('cartCount').textContent=count;document.getElementById('bagItems').textContent=count?`(${count})`:'';document.getElementById('cartTotal').textContent=peso(total)}
function filterProducts(){const query=document.getElementById('search').value.toLowerCase();document.querySelectorAll('#productGrid .card').forEach(card=>{card.style.display=(activeCategory==='All'||card.dataset.category===activeCategory)&&card.dataset.name.includes(query)?'':'none'})}
document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===btn.dataset.view));window.scrollTo({top:0,behavior:'smooth'})}));
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{activeCategory=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===btn));filterProducts()}));
document.querySelectorAll('[data-category-link]').forEach(a=>a.addEventListener('click',()=>{activeCategory=a.dataset.categoryLink;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===activeCategory));filterProducts()}));document.getElementById('search').addEventListener('input',filterProducts);
document.getElementById('productGrid').addEventListener('click',e=>{const btn=e.target.closest('[data-add]');if(!btn)return;const p=products.find(x=>x.id===Number(btn.dataset.add));if(!p)return;let inCart=cart[p.id]?.qty||0;if(inCart>=p.stock){toast('That is all the available stock for this item.');return}cart[p.id]=cart[p.id]||{...p,qty:0};cart[p.id].qty++;renderCart();toast(p.name+' added to your bag.')});
document.getElementById('cartItems').addEventListener('click',e=>{const remove=e.target.closest('[data-remove]'),qty=e.target.closest('[data-qty]');if(remove)delete cart[remove.dataset.remove];if(qty){const id=qty.dataset.qty,step=Number(qty.dataset.step);cart[id].qty+=step;if(cart[id].qty<1)delete cart[id];else if(cart[id].qty>cart[id].stock){cart[id].qty=cart[id].stock;toast('Quantity limited to available stock.')}}renderCart()});
document.getElementById('accountButton').addEventListener('click',()=>{if(<?= $userSignedIn ? 'true' : 'false' ?>)window.location.href='login.php';else document.getElementById('loginModal').classList.add('open')});
document.getElementById('registerLink').addEventListener('click',()=>{window.location.href='registration.php'});
document.getElementById('loginModal').addEventListener('click',e=>{if(e.target.id==='loginModal')e.currentTarget.classList.remove('open')});document.getElementById('openCart').onclick=()=>document.getElementById('cartDrawer').classList.add('open');document.getElementById('closeCart').onclick=()=>document.getElementById('cartDrawer').classList.remove('open');
document.getElementById('checkout').onclick=()=>{if(!Object.keys(cart).length){toast('Add an item to your bag first.');return}document.getElementById('checkoutModal').classList.add('open')};
document.getElementById('checkoutForm').addEventListener('submit',e=>{e.preventDefault();const ref='TF-'+(1049+Math.floor(Math.random()*900));const name=document.getElementById('customerName').value;const total=Object.values(cart).reduce((s,i)=>s+i.qty*i.price,0);const tr=document.createElement('tr');tr.dataset.order=ref;tr.innerHTML=`<td>#${ref}</td><td>${name.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</td><td>Today</td><td>${peso(total)}</td><td><span class="status pending">Pending</span></td><td><select class="order-status" aria-label="Update order ${ref}"><option selected>Pending</option><option>Processing</option><option>Delivered</option><option>Canceled</option></select></td>`;document.getElementById('ordersBody').prepend(tr);cart={};renderCart();document.getElementById('checkoutModal').classList.remove('open');document.getElementById('cartDrawer').classList.remove('open');e.target.reset();toast('Order placed. Reference '+ref+'.')});
document.querySelectorAll('[data-admin]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-admin]').forEach(b=>b.classList.toggle('active',b===btn));document.getElementById('adminHeading').textContent=btn.textContent;document.getElementById('adminProducts').style.display=btn.dataset.admin==='orders'?'none':'';document.getElementById('adminOrders').style.display=btn.dataset.admin==='products'?'none':'';document.querySelector('.stats').style.display=btn.dataset.admin==='overview'?'grid':'none'}));
document.getElementById('adminSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#adminProductRows tr').forEach(row=>row.style.display=row.dataset.adminName.includes(q)?'':'none')});
document.getElementById('ordersBody').addEventListener('change',e=>{if(!e.target.matches('.order-status'))return;const badge=e.target.closest('tr').querySelector('.status');badge.textContent=e.target.value;badge.className='status'+(e.target.value==='Pending'?' pending':e.target.value==='Canceled'?' canceled':'');toast('Order status updated to '+e.target.value+'.')});
document.getElementById('addProduct').addEventListener('click',()=>{document.getElementById('modalTitle').textContent='Add a product';document.getElementById('productModal').classList.add('open')});document.querySelectorAll('[data-close-modal]').forEach(btn=>btn.addEventListener('click',()=>btn.closest('.modal-backdrop').classList.remove('open')));document.querySelectorAll('.modal-backdrop').forEach(back=>back.addEventListener('click',e=>{if(e.target===back)back.classList.remove('open')}));
document.getElementById('productForm').addEventListener('submit',e=>{e.preventDefault();toast('Product details captured. Connect the form to MySQL to save it.');e.target.reset();document.getElementById('productModal').classList.remove('open')});document.getElementById('adminProductRows').addEventListener('click',e=>{if(e.target.matches('[data-edit]'))toast('Product editing form is ready to connect to MySQL.')});document.getElementById('checkoutModal').addEventListener('click',e=>{if(e.target.id==='checkoutModal')e.currentTarget.classList.remove('open')});
renderCart();
</script>
</body></html>

